let COMUNI_CF = null;
function comuneDaCodice(codice) {
  if (!COMUNI_CF) { COMUNI_CF = {}; COMUNI_CF_DATI.split('|').forEach(function (r) { COMUNI_CF[r.slice(0, 4)] = r.slice(4).replace(/~$/, ''); }); }
  const v = COMUNI_CF[String(codice || '').toUpperCase()];
  if (!v) return '';
  const i = v.lastIndexOf('/');
  return i > 0 ? v.slice(0, i) + ' (' + v.slice(i + 1) + ')' : v + ' (stato estero)';
}
// Comune (o stato estero) di nascita dal codice fiscale, es. "MESSINA (ME)"
function comuneDaCF(cf) {
  cf = typeof normalizzaCF === 'function' ? normalizzaCF(cf) : String(cf || '').toUpperCase();
  if (cf.length !== 16) return '';
  const c = typeof datiDaCF === 'function' ? datiDaCF(cf).codiceComune : cf.slice(11, 15);
  return comuneDaCodice(c);
}
